{
  "IP": "neorv32_sdi",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Transmit serial payload data",
      "Unit": "neorv32_sdi",
      "Information": "Payload written through the bus is buffered, loaded into the serial shift register, and transmitted to the SDI peer. SDI transmission depends on preserving this payload.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The payload may be secret and is exposed on the serial output after entering through bus_req_i.data at line 201, being loaded into serial.sreg at line 305, and driving sdi_dat_o at line 345. The payload is sensitive because changes to the bus write value or serial.sreg can change the transmitted data through lines 201, 305, and 345.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could observe sdi_dat_o or alter the bus-to-shift-register data path so that transmitted payloads are disclosed or corrupted.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "sdi_dat_o"
      ],
      "Entry Lines": [
        201
      ],
      "Held Lines": [
        305
      ],
      "Exit Lines": [
        345
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Received serial payload data",
      "Unit": "neorv32_sdi",
      "Information": "Payload received from the SDI peer is shifted into the serial register and returned to software through the receive FIFO and bus response. SDI reception and subsequent software processing depend on preserving this payload.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Received payload may be secret and can be exposed through the bus response after entering from sdi_dat_i at line 270, being shifted into serial.sreg at line 327, and being returned at line 162. The payload is sensitive because corruption of serial.sreg or the returned receive word changes the data software receives, as shown at lines 327 and 162.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could observe the receive readback or modify the receive shift and readback path to disclose or corrupt incoming payloads.",
      "Enters Through": [
        "sdi_dat_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        270
      ],
      "Held Lines": [
        327
      ],
      "Exit Lines": [
        162
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "SDI interface enable state",
      "Unit": "neorv32_sdi",
      "Information": "The enable setting controls whether the SDI interface and its transmit and receive FIFOs operate. It is written through the bus and can be read back as part of the control configuration.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The enable state is sensitive configuration stored from bus_req_i.data at line 133 and can be modified by a bus write. Clearing or changing it clears both FIFOs at lines 200 and 239 and controls serial operation through line 296, so an attacker can disable the interface or discard transfers.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could write the control register to clear the enable state, disabling serial processing and clearing queued data.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        133
      ],
      "Held Lines": [
        133
      ],
      "Exit Lines": [
        143
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "SDI chip-select and transaction selection",
      "Unit": "neorv32_sdi",
      "Information": "The chip-select value frames and selects an SDI transaction: assertion starts a transfer and deassertion terminates or prevents progress. Its active state is also reported through the bus status readback.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The chip-select decision controls serial start and state transitions at lines 307, 315, and 324, so corruption can cause data to be captured in the wrong transaction or outside the intended frame. An inactive or manipulated chip-select can prevent or terminate a required transfer through the same conditions at lines 307, 315, and 324.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could force or corrupt the chip-select condition so that transfers are started spuriously, terminated early, or prevented from starting.",
      "Enters Through": [
        "sdi_csn_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        269
      ],
      "Held Lines": [],
      "Exit Lines": [
        160
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "FIFO event interrupt request",
      "Unit": "neorv32_sdi",
      "Information": "The interrupt request reports enabled receive and transmit FIFO threshold events to the host. Host servicing of queued receive data and transmit capacity can depend on this notification.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The interrupt output is a security-relevant status and control indication because the logic at lines 249 through 254 combines FIFO conditions and interrupt enables to produce irq_o; modifying that result can cause false or missing service requests.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An attacker could force irq_o asserted or deasserted, causing spurious servicing or preventing the host from servicing pending FIFO data.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        249
      ],
      "Exit Lines": [
        249
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Interrupt threshold-enable settings",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C5",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "FIFO occupancy and flow-control status",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The FIFO status bits reported at lines 153 through 158 and used at lines 250 through 254 only describe whether buffered payload data can move or generate an interrupt, so the buffer-status rule bars them as independent conceptual assets."
    },
    {
      "Candidate Name": "Serial engine sequencing state and counters",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "serial.state and serial.cnt at lines 297 through 340 only sequence, count, and time the serial transfer, so the sequencing-state and pacing rules bar them as independent information."
    },
    {
      "Candidate Name": "Input synchronizer state",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The synchronizer registers at lines 264 through 270 and derived signals at lines 274 through 276 only resample external clock, chip-select, and data inputs, so synchronizer stages are working copies rather than separate conceptual assets."
    },
    {
      "Candidate Name": "Bus access commands and response handshakes",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The bus strobe, direction, address selection, acknowledge, and constant error behavior at lines 125 through 165 are access-command fields or handshake copies, which the access-command and bus-handshake rules bar as separate pieces."
    },
    {
      "Candidate Name": "FIFO size build-time configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "RTX_FIFO and its derived size at lines 20, 61, and 145 only fix implementation depth at build time and cannot be changed or withheld at run time."
    },
    {
      "Candidate Name": "SDI and module clock/reset lines",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "clk_i, rstn_i, and the serial clock are timing or reset inputs at lines 23, 24, and 28, and the clock/reset rules bar them as conceptual assets."
    }
  ],
  "Notes": []
}
